GP = [("Qwen3-VL-2B, zero-shot", ["R0_zs"]), ("ECT", ["T1v4_s0", "T1v4_s1", "T1v4_s2", "T1v4_s3"]), ("+ clean", ["ABL_noND"]), ("+ notdone", ["ABL_noCL"]), ("No paired neg.", ["ABL_none", "ABL_none_s1"]), ("No neg., re-balanced sampling", ["T1v2_2400"])]
table("tab_probe", "lccc", "Model & $n$ & AUROC, completion & AUROC, mistake", [(n, len(ks), f"{m([G[k]['auroc_done'] for k in ks]):.3f}", f"{m([G[k]['auroc_mis'] for k in ks]):.3f}") for n, ks in GP],
      "Separability of the first-token probability of ``yes'' on 1,233 fixed validation situations (positive situations against silence). On this probe the variants without clean negatives separate mistakes \\emph{better} than ECT: the negatives move the operating point, they do not sharpen discrimination.", "tab:probe")
for n, ks in GP: NUM[f"probe_{n}"] = [m([G[k]["auroc_done"] for k in ks]), m([G[k]["auroc_mis"] for k in ks])]

